 static void Guides(){Physics.SyncTransforms();var oldL=AssetDatabase.LoadAssetAtPath<Mesh>(E+"CF_R1_Continuous_L.asset").vertices;var oldR=AssetDatabase.LoadAssetAtPath<Mesh>(E+"CF_R1_Continuous_R.asset").vertices;var parent=root.Find("Facility_Floor_Guidance_R1");
 foreach(string side in new[]{"L","R"}){var old=side=="L"?oldL:oldR;var v=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();float along=0;Vector3 prev=Vector3.zero;
 for(int seg=0;seg<old.Length/2-1;seg++){var c0=(oldL[seg*2]+oldL[seg*2+1]+oldR[seg*2]+oldR[seg*2+1])*.25f;var c1=(oldL[seg*2+2]+oldL[seg*2+3]+oldR[seg*2+2]+oldR[seg*2+3])*.25f;float z0=(Quaternion.Inverse(Q)*(parent.TransformPoint(c0)-P)).z,z1=(Quaternion.Inverse(Q)*(parent.TransformPoint(c1)-P)).z;var splits=new SortedSet<float>{0,1};if(Mathf.Abs(z1-z0)>.0001f){for(float z=0;z<=L;z+=.15f){float t=(z-z0)/(z1-z0);if(t>0&&t<1)splits.Add(t);}foreach(float z in new[]{L,1.25f,L-1.25f}){float t=(z-z0)/(z1-z0);if(t>0&&t<1)splits.Add(t);}}
 if(Mathf.Abs(z1-z0)>.0001f)foreach(float endpoint in new[]{0f,L})for(float z=endpoint-.8f;z<=endpoint+.8f;z+=.025f){float t=(z-z0)/(z1-z0);if(t>0&&t<1)splits.Add(t);}
 foreach(float t in splits){if(seg>0&&t==0)continue;var center=Vector3.Lerp(c0,c1,t);var local=Quaternion.Inverse(Q)*(parent.TransformPoint(center)-P);float blend=Mathf.SmoothStep(0,1,Mathf.Min(local.z,L-local.z)/1.25f);if(local.z<0||local.z>L)blend=0;var delta=parent.InverseTransformVector(Q*(Vector3.left*local.x*blend));if(v.Count>0)along+=Vector3.Distance(prev,center+delta);prev=center+delta;
