 for(int i=0;i<v.Count;i++){var world=parent.TransformPoint(v[i]);var local=Quaternion.Inverse(Q)*(world-P);if(Mathf.Abs(local.z)<.8f||Mathf.Abs(local.z-L)<.8f){var hits=Physics.RaycastAll(world+Vector3.up*.2f,Vector3.down,.4f,~0,QueryTriggerInteraction.Ignore).Where(h=>h.normal.y>.8f&&h.collider.transform.IsChildOf(root)).ToArray();if(hits.Length>0){world.y=Mathf.Max(world.y,hits.Max(h=>h.point.y)+.0035f);v[i]=parent.InverseTransformPoint(world);}}}
 for(int i=tr.Count-3;i>=0;i-=3)if(Vector3.Cross(v[tr[i+1]]-v[tr[i]],v[tr[i+2]]-v[tr[i]]).sqrMagnitude<1e-14f)tr.RemoveRange(i,3);
 var target=parent.GetComponentsInChildren<MeshFilter>().Single(f=>AssetDatabase.GetAssetPath(f.sharedMesh).EndsWith("_"+side+".asset"));target.sharedMesh=Save("TC_R1_Continuous_"+side,v,tr,uv);}
 }
