 Mat("TC_Coat",Color.white,.12f,.45f,"TC_Coat_Base");Mat("TC_Floor",Color.white,.02f,.29f,"TC_Floor_Base");Mat("TC_Steel",Color.white,.8f,.62f,"TC_Steel_Base");Mat("TC_Dark",new Color(.037f,.047f,.053f),.06f,.32f);Mat("TC_Cable",new Color(.045f,.063f,.068f),.05f,.52f);Mat("TC_Teal",new Color(.10f,.28f,.29f),.35f,.60f);Mat("TC_Lens",new Color(.025f,.070f,.095f),.72f,.88f);Mat("TC_Rib",new Color(.65f,.71f,.74f),.68f,.46f);Mat("TC_Label_C01",Color.white,0,.18f,"TC_Floor_C01",true);Mat("TC_Label_C02",Color.white,0,.18f,"TC_Floor_C02",true);
 foreach(var file in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Environment/B5"),"TC_T01_*.fbx")){var path=E+Path.GetFileName(file);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(var mat in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),mat.Key),mat.Value);mi.SaveAndReimport();}
